#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64

// Адрес дисплея: 0x3C или 0x3D. Если сканер показал 0x3D — замените здесь.
#define OLED_ADDRESS 0x3C

Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, -1);

void setup() {
  Serial.begin(9600);

  // Инициализация дисплея
  if (!display.begin(SSD1306_SWITCHCAPVCC, OLED_ADDRESS)) {
    Serial.println(F("Не удалось найти дисплей по адресу 0x3C! Проверьте подключение или попробуйте 0x3D."));
    for (;;);
  }

  display.clearDisplay();
  display.setTextColor(SSD1306_WHITE);
  display.setTextSize(1); // Размер шрифта: 1 — стандартный, компактный

  drawAllChars();
}

void drawAllChars() {
  int x = 0, y = 0;
  const int charWidth = 6;   // ширина символа в пикселях (для шрифта size 1)
  const int charHeight = 8;  // высота символа
  const int cols = SCREEN_WIDTH / charWidth;

  // 1. Заглавные буквы A–Z
  display.setCursor(0, y);
  display.println("A-Z:");
  y += charHeight;
  x = 0;
  for (char c = 'A'; c <= 'Z'; c++) {
    if (x + charWidth > SCREEN_WIDTH) {
      x = 0; y += charHeight;
    }
    display.drawChar(x, y, c, SSD1306_WHITE, SSD1306_BLACK, 1);
    x += charWidth;
  }
  y += charHeight;

  // 2. Строчные буквы a–z
  display.setCursor(0, y);
  display.println("a-z:");
  y += charHeight;
  x = 0;
  for (char c = 'a'; c <= 'z'; c++) {
    if (x + charWidth > SCREEN_WIDTH) {
      x = 0; y += charHeight;
    }
    display.drawChar(x, y, c, SSD1306_WHITE, SSD1306_BLACK, 1);
    x += charWidth;
  }
  y += charHeight;

  // 3. Цифры 0–9
  display.setCursor(0, y);
  display.println("0-9:");
  y += charHeight;
  x = 0;
  for (char c = '0'; c <= '9'; c++) {
    if (x + charWidth > SCREEN_WIDTH) {
      x = 0; y += charHeight;
    }
    display.drawChar(x, y, c, SSD1306_WHITE, SSD1306_BLACK, 1);
    x += charWidth;
  }
  y += charHeight;

  // 4. Специальные символы (ASCII 33–64, кроме уже выведенных букв/цифр)
  display.setCursor(0, y);
  display.println("Special:");
  y += charHeight;
  x = 0;
  for (int code = 33; code <= 64; code++) {
    char c = (char)code;
    // Пропускаем буквы и цифры, если они уже были (но в этом диапазоне их нет)
    if (x + charWidth > SCREEN_WIDTH) {
      x = 0; y += charHeight;
    }
    // Защита от выхода за пределы экрана по вертикали
    if (y + charHeight > SCREEN_HEIGHT) break;
    display.drawChar(x, y, c, SSD1306_WHITE, SSD1306_BLACK, 1);
    x += charWidth;
  }

  display.display();
}

void loop() {
  // Здесь можно добавить прокрутку, анимацию или другие эффекты
}
